The task: identify start bit (0), then 8 data bits, then check stop bit (1). If stop bit is not 1 when expected, wait until a stop bit found before attempting next byte.

The standard HDLBits solution (Fsm serial):

```
module top_module(
    input clk,
    input in,
    input reset,
    output done
); 
    parameter IDLE=0, START=1, DATA=2, STOP=3, ERROR=4;
    reg [2:0] state, next_state;
    reg [3:0] cnt;

    always @(*) begin
        case (state)
            IDLE: next_state = in ? IDLE : START;
            START: next_state = DATA;
            DATA: next_state = (cnt == 8) ? STOP : DATA;
            STOP: next_state = in ? IDLE : ERROR;  // Actually the official solution: STOP: next_state = in ? IDLE : STOP; hmm
            ERROR: next_state = in ? IDLE : ERROR;
        endcase
    end
```

